1	const priceList: Record<string, number> = {
2	  sword: 100,
3	  amulet: 60,
4	  staff: 80,
5	  potion: 40,
6	  rune: 25,
7	};
8	
9	type Item = { type: string };
10	
11	export const basePremium = (items: Item[]): number =>
12	  items.reduce((sum, item) => sum + priceList[item.type], 0);
13	
14	export const runScenario = (_scenario: unknown): unknown => undefined;
15

1	import { describe, it, expect } from "vitest";
2	import { basePremium, runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Base premiums for main items (price list) ---
6	  it("basePremium: a sword → 100 G base premium", () => {
7	    expect(basePremium([{ type: "sword" }])).toBe(100);
8	  });
9	  it("basePremium: an amulet → 60 G base premium", () => {
10	    expect(basePremium([{ type: "amulet" }])).toBe(60);
11	  });
12	  it("basePremium: a staff → 80 G base premium", () => {
13	    expect(basePremium([{ type: "staff" }])).toBe(80);
14	  });
15	  it("basePremium: a potion → 40 G base premium", () => {
16	    expect(basePremium([{ type: "potion" }])).toBe(40);
17	  });
18	
19	  // --- Component pricing and the building block of 3 alike components ---
20	  it("basePremium: a single rune → 25 G base premium", () => {
21	    expect(basePremium([{ type: "rune" }])).toBe(25);
22	  });
23	  it("basePremium: 2 runes → 50 G base premium (no block)", () => {
24	    expect(basePremium([{ type: "rune" }, { type: "rune" }])).toBe(50);
25	  });
26	  it.todo("basePremium: 3 runes → 60 G base premium (block applies)");
27	  it.todo("basePremium: 4 runes → 100 G base premium (no block — block requires exactly 3)");
28	  it.todo("basePremium: 7 runes → 175 G base premium");
29	
30	  // --- "Alike" components: block requires same type ---
31	  it.todo("basePremium: 2 runes + 1 moonstone → 75 G base premium (no block: different types)");
32	  it.todo("basePremium: 3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
33	
34	  // --- Processing fee and empty policy ---
35	  it.todo("quote: empty item list → premium 5 G (only the processing fee)");
36	
37	  // --- Individual premium modifiers ---
38	  it.todo("quote: newcomer with a cursed sword (0 yrs, steel, enchantment 3) → premium 165 G");
39	  it.todo("quote: high-enchantment surcharge applies at exactly enchantment 5");
40	  it.todo("quote: enchantment 4 → no high-enchantment surcharge");
41	  it.todo("quote: cursed sword with enchantment 5 → both curse and high-enchantment surcharges apply");
42	  it.todo("quote: customer with exactly 2 years → loyalty discount applies");
43	
44	  // --- Modifier scope on multi-item policies ---
45	  it.todo("quote: cursed surcharge is 50% of the cursed item's base premium, not of the policy total");
46	  it.todo("quote: each item in a quote is treated as a first insurance regardless of customer history");
47	
48	  // --- Integration examples ---
49	  it.todo("quote: long-standing customer's second contract, cursed sword enchantment 7 (3 yrs) → premium 160 G");
50	
51	  // --- Rounding in the MHPCO's favor ---
52	  it.todo("quote: a premium that yields 197.5 G → final premium 198 G (rounded up)");
53	  it.todo("claim: a payout that yields 350.5 G → final payout 350 G (rounded down)");
54	
55	  // --- Claim processing: standard reimbursement ---
56	  it.todo("claim: regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
57	  it.todo("claim: rune (value 250 G), damage 200 G → payout 100 G (no special clause)");
58	
59	  // --- Claim processing: enchantment threshold vs dragon material ---
60	  it.todo("claim: dragon-material sword enchantment 8, damage 1000 G → payout 400 G (50% then deductible)");
61	  it.todo("claim: dragon-material sword enchantment 5, damage 800 G → payout 700 G (full then deductible)");
62	  it.todo("claim: steel sword enchantment 9, damage 1000 G → payout 400 G (50% then deductible)");
63	  it.todo("claim: dragon-material sword enchantment 9, damage 1000 G → payout 400 G (50% rule wins)");
64	
65	  // --- Deductible per damage event ---
66	  it.todo("claim: dragon attack damages sword 500 G and amulet 300 G → payout 600 G (deductible per item)");
67	
68	  // --- Multiple items of the same type ---
69	  it.todo("claim: two swords, damages to both → each entry is a separate damage with its own deductible");
70	  it.todo("claim: more damage entries of a type than the policy covers → whole claim rejected (throws)");
71	
72	  // --- Insurance sum and cap ---
73	  it.todo("claim: cursed sword cap is 2000 G, based on the unmodified insurance value");
74	  it.todo("claim: sword + amulet → insurance sum 1600 G, cap 3200 G");
75	  it.todo("claim: sword + 3 runes (block) → insurance sum 1750 G (block affects premium only)");
76	
77	  // --- Cap exhaustion across successive claims ---
78	  it.todo("claim: sword (cap 2000 G), two 1500 G claims → 1400 G (rem 600), then 600 G (rem 0)");
79	
80	  // --- Error handling / edge cases ---
81	  it.todo("quote: unknown item type (e.g. broomstick) → throws (non-zero exit, error to stderr)");
82	  it.todo("claim: damage entry for an item not in the policy → throws");
83	  it.todo("claim: damage entry with a negative amount → throws");
84	
85	  // --- End-to-end multi-step scenario (CLI shape) ---
86	  it.todo("runScenario: quote then claim produces results in the same order as steps");
87	});
